import {
    Table,
    StringColumn,
    ReferenceColumn,
    DecimalColumn,
    DocumentIdColumn,
    SystemClassNameColumn,
    DateTimeColumn,
    IntegerColumn,
} from '../../db'

export const sys_variable_value = Table({
    name: 'sys_variable_value',
    schema: {
        document: StringColumn({}),
        value: StringColumn({}),
        variable: ReferenceColumn({ referenceTable: 'var_dictionary' }),
        order: DecimalColumn({}),
        document_key: DocumentIdColumn({ dependent: 'document' }),
        sys_class_name: SystemClassNameColumn({
            default: 'javascript:current.getTableName();',
            dropdown: 'dropdown_without_none',
            label: 'Class',
            maxLength: 80,
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                },
            ],
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                },
            ],
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                },
            ],
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                },
            ],
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                },
            ],
        }),
    },
})
